	db, err := prepareDatabase(t.Context(), t)
	if err != nil {
		t.Fatalf("prepareDatabase() error = %v", err)
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()

			h := newTestHandler(t, db, tt.grants)

			req := httptest.NewRequestWithContext(t.Context(), tt.method, tt.target, strings.NewReader(tt.body))
			for name, value := range tt.headers {
				req.Header.Set(name, value)
			}
			rr := httptest.NewRecorder()
			h.ServeHTTP(rr, req)

			if !slices.Contains(tt.wantStatuses, rr.Result().StatusCode) {
				t.Errorf("status = %d, want one of %v; body: %s", rr.Result().StatusCode, tt.wantStatuses, rr.Body.String())
			}
		})
	}
